INSERT INTO `offices` VALUES (1,'kantor 1','banguntapan',30,'https://bit.ly/40Ql4eX','http://bit.ly/corevaluedantatatertib','1. Wajib hadir dan absen tepat waktu sesuai shift.\r\n2. Berpakaian rapi, sopan, dan mengenakan tanda pengenal/ID Card magang.\r\n3. Menjaga ketertiban, kebersihan, dan kenyamanan lingkungan kantor.\r\n4. Mematuhi batas waktu istirahat dan konfirmasi ke atasan jika ada keperluan izin.\r\n5. Dilarang merokok dan menjaga fasilitas kerja dengan baik.','https://docs.google.com/spreadsheets/d/1h5DheP6hp1gVteWE8Fm9b0oVk35gYsrQ/edit?usp=sharing&ouid=108069506443698214788&rtpof=true&sd=true',NULL),(2,'kantor 4','banguntapan',30,'https://bit.ly/40Ql4eX','http://bit.ly/corevaluedantatatertib','1. Wajib hadir dan absen tepat waktu sesuai shift.\r\n2. Berpakaian rapi, sopan, dan mengenakan tanda pengenal/ID Card magang.\r\n3. Menjaga ketertiban, kebersihan, dan kenyamanan lingkungan kantor.\r\n4. Mematuhi batas waktu istirahat dan konfirmasi ke atasan jika ada keperluan izin.\r\n5. Dilarang merokok dan menjaga fasilitas kerja dengan baik.','https://docs.google.com/spreadsheets/d/1h5DheP6hp1gVteWE8Fm9b0oVk35gYsrQ/edit?usp=sharing&ouid=108069506443698214788&rtpof=true&sd=true',NULL),(3,'kantor 2','banguntapan',30,'https://bit.ly/40Ql4eX','http://bit.ly/corevaluedantatatertib','1. Wajib hadir dan absen tepat waktu sesuai shift.\r\n2. Berpakaian rapi, sopan, dan mengenakan tanda pengenal/ID Card magang.\r\n3. Menjaga ketertiban, kebersihan, dan kenyamanan lingkungan kantor.\r\n4. Mematuhi batas waktu istirahat dan konfirmasi ke atasan jika ada keperluan izin.\r\n5. Dilarang merokok dan menjaga fasilitas kerja dengan baik.','https://docs.google.com/spreadsheets/d/1h5DheP6hp1gVteWE8Fm9b0oVk35gYsrQ/edit?usp=sharing&ouid=108069506443698214788&rtpof=true&sd=true',NULL);
